using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;
using UnityEngine.Scripting;
namespace UnityEngine.Scripting{class PreserveAttribute:Attribute{}}
public class World{}public class GameManager{}public enum NetPackageDirection{ToServer,ToClient}
public class NetPackage{internal bool NativeSender=true;public virtual NetPackageDirection PackageDirection=>0;public virtual void read(PooledBinaryReader reader){}public virtual void write(PooledBinaryWriter writer){}public virtual void ProcessPackage(World world,GameManager callbacks){}internal bool ValidEntityIdForSender(int player)=>NativeSender&&player==7;}
public class PooledBinaryWriter:BinaryWriter{internal PooledBinaryWriter(Stream stream):base(stream,Encoding.UTF8,true){}}
public class PooledBinaryReader:BinaryReader{internal PooledBinaryReader(Stream stream):base(stream,Encoding.UTF8,true){}}
static class RebirthProductiveEarnedUiDeferredTransport{internal static Dictionary<NetPackage,object> Received=new Dictionary<NetPackage,object>();internal static void ForgetReceivedConnection(NetPackage packet){Received.Remove(packet);}}
static class RebirthCookingGridCustody{internal static void WriteWireString(PooledBinaryWriter writer,string text,int max){if(text==null||text.Length>max)throw new InvalidDataException();writer.Write(text);}internal static string ReadWireString(PooledBinaryReader reader,int max){string text=reader.ReadString();if(text.Length>max)throw new InvalidDataException();return text;}}
static class RebirthRemoteResourceFragments{internal const int ChunkText=40000;internal class Body{internal string Hash=new string('a',64);internal int Length=3,Count=1;internal string Part(int part){if(part!=0)throw new Exception();return "YWJj";}}}
static class RebirthCamperRemovalParcelTransport{internal static int Receives;internal static bool Server;internal static void Receive(RebirthCamperRemovalParcelPacket packet,World world,GameManager manager,bool server){Receives++;Server=server;}}
// ACTUAL_PACKETS
static class Program
{
 static int count;static void Check(bool value){count++;if(!value)throw new Exception("Actual parcel packet assertion "+count);}
 static byte[] Bytes(NetPackage packet){using(var stream=new MemoryStream()){using(var writer=new PooledBinaryWriter(stream))packet.write(writer);return stream.ToArray();}}
 static bool Read(NetPackage packet,byte[] bytes){try{using(var stream=new MemoryStream(bytes))using(var reader=new PooledBinaryReader(stream)){packet.read(reader);return stream.Position==stream.Length;}}catch{return false;}}
 static void Main(){Guid operation=Guid.NewGuid();var body=new RebirthRemoteResourceFragments.Body();var request=new NetPackageRebirthRemovalParcelRequest();RebirthProductiveEarnedUiDeferredTransport.Received[request]=new object();request.Setup(7,operation,"world","creation",body,0);Check(!RebirthProductiveEarnedUiDeferredTransport.Received.ContainsKey(request));Check(request.ValidActorSender());request.NativeSender=false;Check(!request.ValidActorSender());request.NativeSender=true;
 var bytes=Bytes(request);var decoded=new NetPackageRebirthRemovalParcelRequest();RebirthProductiveEarnedUiDeferredTransport.Received[decoded]=new object();Check(Read(decoded,bytes)&&!RebirthProductiveEarnedUiDeferredTransport.Received.ContainsKey(decoded));Check(decoded.Player==7&&decoded.Operation==operation&&decoded.NativeWorld=="world"&&decoded.Creation=="creation"&&decoded.Hash==body.Hash&&decoded.Total==3&&decoded.Count==1&&decoded.Index==0&&decoded.Fragment=="YWJj");Check(bytes.SequenceEqual(Bytes(decoded)));Check(decoded.PackageDirection==NetPackageDirection.ToServer);
 var result=new NetPackageRebirthRemovalParcelResult().Setup(7,operation,"world","creation",body,0);Check(result.PackageDirection==NetPackageDirection.ToClient);decoded.ProcessPackage(new World(),new GameManager());Check(RebirthCamperRemovalParcelTransport.Receives==1&&RebirthCamperRemovalParcelTransport.Server);result.ProcessPackage(new World(),new GameManager());Check(RebirthCamperRemovalParcelTransport.Receives==2&&!RebirthCamperRemovalParcelTransport.Server);
 var corrupt=(byte[])bytes.Clone();corrupt[0]^=1;RebirthProductiveEarnedUiDeferredTransport.Received[decoded]=new object();Check(!Read(decoded,corrupt)&&!RebirthProductiveEarnedUiDeferredTransport.Received.ContainsKey(decoded));Check(!Read(decoded,bytes.Take(12).ToArray()));request.Setup(7,operation,new string('w',65),"creation",body,0);bool blocked=false;try{Bytes(request);}catch(InvalidDataException){blocked=true;}Check(blocked);Console.WriteLine(count+" actual parcel packet assertions passed");}
}
